package io.github.norbertweb.bluebird.editor.editor.actions
import androidx.compose.ui.text.TextRange
import androidx.compose.ui.text.input.TextFieldValue
data class ActionResult(val newValue: TextFieldValue, val shouldRecord: Boolean = true)
private fun move(v: TextFieldValue, target: Int, extend: Boolean) = ActionResult(v.copy(selection = if (extend) TextRange(v.selection.start, target) else TextRange(target)), false)
fun moveLeft(v: TextFieldValue, extend: Boolean = false, byWord: Boolean = false): ActionResult { val t = if (!extend && !v.selection.collapsed) v.selection.min else if (byWord) v.text.substring(0, v.selection.start).trimEnd().lastIndexOfAny(charArrayOf(' ','\n','\t')).let { if (it < 0) 0 else it+1 } else (v.selection.start-1).coerceAtLeast(0); return move(v,t,extend) }
fun moveRight(v: TextFieldValue, extend: Boolean = false, byWord: Boolean = false): ActionResult { val t = if (!extend && !v.selection.collapsed) v.selection.max else if (byWord) v.text.indexOfAny(charArrayOf(' ','\n','\t'),v.selection.end).let { if (it<0) v.text.length else it } else (v.selection.end+1).coerceAtMost(v.text.length); return move(v,t,extend) }
fun moveHome(v: TextFieldValue, extend: Boolean = false, document: Boolean = false): ActionResult { val t=if(document)0 else v.text.lastIndexOf('\n',(v.selection.start-1).coerceAtLeast(0))+1; return move(v,t,extend) }
fun moveEnd(v: TextFieldValue, extend: Boolean = false, document: Boolean = false): ActionResult { val e=v.text.indexOf('\n',v.selection.start); val t=if(document)v.text.length else if(e<0)v.text.length else e; return move(v,t,extend) }
fun deleteBackward(v: TextFieldValue, byWord: Boolean = false): ActionResult { if(!v.selection.collapsed)return ActionResult(v.copy(text=v.text.removeRange(v.selection.min,v.selection.max),selection=TextRange(v.selection.min))); val s=if(byWord)v.text.substring(0,v.selection.start).trimEnd().lastIndexOfAny(charArrayOf(' ','\n','\t')).let{if(it<0)0 else it+1}else(v.selection.start-1).coerceAtLeast(0); return if(s==v.selection.start)ActionResult(v,false)else ActionResult(v.copy(text=v.text.removeRange(s,v.selection.start),selection=TextRange(s))) }
fun deleteForward(v: TextFieldValue, byWord: Boolean = false): ActionResult { if(!v.selection.collapsed)return ActionResult(v.copy(text=v.text.removeRange(v.selection.min,v.selection.max),selection=TextRange(v.selection.min))); val e=if(byWord)v.text.indexOfAny(charArrayOf(' ','\n','\t'),v.selection.start).let{if(it<0)v.text.length else it}else(v.selection.start+1).coerceAtMost(v.text.length); return if(e==v.selection.start)ActionResult(v,false)else ActionResult(v.copy(text=v.text.removeRange(v.selection.start,e))) }
